"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["21396"],{5741(e){e.exports=JSON.parse('{"id":"FIN-637","slug":"semi-variable-cost","term":"Semi-Variable Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A semi-variable cost is a cost that has both a fixed part, paid regardless of activity, and a variable part that changes with the level of activity.","explanation":["Many real-world costs combine fixed and variable elements. They are also called mixed costs.","A common example is a phone plan with a fixed monthly charge of 50 plus 0.10 for each minute of calls. A business that makes 2,000 minutes of calls pays 50 plus 200, a total of 250. If it makes 4,000 minutes, it pays 450. The cost rises with use, but not in direct proportion, because of the fixed element.","Other examples include utility bills with a standing charge plus usage charges, maintenance costs that include routine servicing plus extra repairs when machines are used more heavily, and sales staff paid a base salary plus commission.","For budgeting and analysis, businesses often split semi-variable costs into their fixed and variable parts. This makes it easier to forecast costs at different levels of activity and to calculate break-even points accurately.","Understanding which costs are fixed, variable or semi-variable helps managers predict how profits will respond to changes in sales and plan how to adjust costs when conditions change."],"note":"","total":1725,"prev":{"slug":"selling-expense","term":"Selling Expense"},"next":{"slug":"senior-debt","term":"Senior Debt"}}')}}]);